impl<E> Policy<Request, Response, E> for Attempts {
    type Future = future::Ready<()>;
    fn retry(&mut self, _req: &mut Request, result: &mut Result<Response, E>) -> Option<Self::Future> {
        match result { Ok(_) => None, Err(_) if self.0 > 0 => { self.0 -= 1; Some(future::ready(())) }, Err(_) => None }
    }
    fn clone_request(&mut self, req: &Request) -> Option<Request> { Some(req.clone()) }
}
let svc = ServiceBuilder::new().layer(RetryLayer::new(Attempts(3))).service(client);

